WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, COUNT(c.Id) AS CommentCount, ROW_NUMBER() OVER (PARTITION BY p.Id ORDER BY p.CreationDate DESC NULLS FIRST) AS rn FROM Posts AS p LEFT JOIN Comments AS c ON p.Id = c.PostId GROUP BY p.Id, p.Title, p.CreationDate, p.Score, p.ViewCount), UserReputation AS (SELECT u.Id AS UserId, u.Reputation, COUNT(b.Id) AS BadgeCount, AVG(v.BountyAmount) AS AvgBounty FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId LEFT JOIN Votes AS v ON u.Id = v.UserId GROUP BY u.Id, u.Reputation), ClosedPosts AS (SELECT ph.PostId, ph.CreationDate, GROUP_CONCAT(ct.Name, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS ct ON CAST(ph.Comment AS Nullable(Int32)) = ct.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId, ph.CreationDate), HighScorePosts AS (SELECT rp.PostId, rp.Title, rp.CreationDate, rp.Score, rp.ViewCount, rp.CommentCount, COALESCE(cp.CloseReasons, 'No Close Reason') AS CloseReason FROM RankedPosts AS rp LEFT JOIN ClosedPosts AS cp ON rp.PostId = cp.PostId WHERE rp.Score > (SELECT AVG(Score) FROM Posts)) SELECT hsp.PostId, hsp.Title, hsp.CreationDate, hsp.Score, hsp.ViewCount, hsp.CommentCount, hsp.CloseReason, ur.UserId, ur.Reputation, ur.BadgeCount, ur.AvgBounty FROM HighScorePosts AS hsp JOIN Users AS u ON hsp.PostId = u.Id JOIN UserReputation AS ur ON u.Id = ur.UserId ORDER BY hsp.Score DESC NULLS FIRST, ur.Reputation DESC NULLS FIRST LIMIT 50